WITH scored AS (SELECT id, product_id, sale_date, units, SUM(revenue) OVER (PARTITION BY product_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue, CORR(units, revenue) OVER w_running AS corr_units_revenue FROM store_sales WINDOW w_running AS (PARTITION BY product_id)) SELECT s.id, s.product_id, s.sale_date, s.units, (SELECT AVG(i2.quantity) FROM inventory i2 WHERE i2.product_id = s.product_id) AS avg_inventory_quantity FROM scored s;
